mapper.insert:
insert into exam_question (
    question_type, question_stem, options_json, correct_answer,
    answer_analysis, difficulty, status, created_by
)
values (
    #{questionType}, #{questionStem}, #{optionsJson}, #{correctAnswer},
    #{answerAnalysis}, #{difficulty}, #{status}, #{createdBy}
)

mapper.delete:
delete from exam_question
where id = #{id}
  and not exists (
      select 1 from exam_paper_question epq where epq.question_id = exam_question.id
  )

mapper.select:
select *
from exam_question


        question_stem like concat('%', #{keyword}, '%')


        and question_type = #{questionType}


        and status = #{status}


order by id desc

mapper.insert:
insert into exam_paper (
    paper_name, description, duration_minutes, total_score,
    pass_score, status, created_by
)
values (
    #{paperName}, #{description}, #{durationMinutes}, #{totalScore},
    #{passScore}, #{status}, #{createdBy}
)

insert into exam_schedule (
    paper_id, class_id, exam_name, start_time, end_time,
    status, answer_published, created_by
)
values (
    #{paperId}, #{classId}, #{examName}, #{startTime}, #{endTime},
    #{status}, #{answerPublished}, #{createdBy}
)

mapper.select:



        es.exam_name like concat('%', #{keyword}, '%')


        and es.class_id = #{classId}


        and es.status = #{status}


order by es.start_time desc, es.id desc

select ea.*, es.exam_name, ep.total_score as paper_total_score
from exam_attempt ea
join exam_schedule es on es.id = ea.schedule_id
join exam_paper ep on ep.id = es.paper_id
where ea.schedule_id = #{scheduleId}
  and ea.student_id = #{studentId}

mapper.update:
update exam_answer
set answer_content = #{answerContent}
where id = #{id}
  and attempt_id = #{attemptId}
  and exists (
      select 1
      from exam_attempt attempt
      where attempt.id = exam_answer.attempt_id
        and attempt.status = 'IN_PROGRESS'
  )

update exam_answer
set is_correct = #{correct},
    score = #{score}
where id = #{id}
